message.content:
{
  "title": "the_banner_rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined outer gate.",
      "visual_description": "Crumbled stone archway with rusted portcullis half-raised, old royal banners hanging torn from the battlements, party silhouettes against a dusty sunset.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings.",
      "visual_description": "Huddled figures in threadbare cloaks point toward the inner city, their faces hidden in shadow, a child clutching a broken doll.",
      "characters": ["townspeople", "map_reader", "scout"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrol blocks the market street.",
      "visual_description": "Helmeted guards in dented breastplates march in formation past stalls with faded awnings, spears glinting in narrow shafts of light.",
      "characters": ["patrol_guard_leader", "patrol_guard_follower", "scout", "magic_helper"]
    },
    {
      "scene_number": 4,
      "caption": "The scout lures the patrol away.",
      "visual_description": "Scout ducks behind a toppled fountain, then tosses a pebble that clatters down a side alley, drawing the guards after the sound.",
      "characters": ["scout", "patrol_guard_leader", "patrol_guard_follower"]
    },
    {
      "scene_number": 5,
      "caption": "The magic helper opens a sealed door.",
      "visual_description": "Stone door carved with a rune ring glows as the magic helper presses a crystal key into its center lock, dust shaking from the arch.",
      "characters": ["magic_helper", "map_reader"]
    },
    {
      "scene_number": 6,
      "caption": "They enter the cursed tower's base chamber.",
      "visual_description": "Circular room with a spiral stair winding upward, broken stained-glass shards on the floor reflecting colored light, a torn banner half-burned in a brazier.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 7,
      "caption": "A mirror hall reflects false paths.",
      "visual_description": "Endless corridor of floor-to-ceiling mirrors showing multiple copies of the party, a single correct door hidden among reflections.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 8,
      "caption": "The scout finds the real door by touch.",
      "visual_description": "Scout runs fingers along the mirror frames until one clicks inward, the reflection rippling to reveal a narrow passage beyond.",
      "characters": ["scout", "map_reader", "magic_helper"]
    },
    {
      "scene_number": 9,
      "caption": "Rumors of a dragon echo from above.",
      "visual_description": "High arched ceiling with a stone balcony, a low growl and a rush of warm air from a dark opening, party members looking up with wide eyes.",
      "characters": ["map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 10,
      "caption": "The rescue target is found in the old plaza.",
      "visual_description": "Central plaza with a cracked fountain statue, a bound figure in tattered robes kneeling beside the basin, surrounded by fallen royal banners.",
      "characters": ["map_reader", "scout", "magic_helper", "rescue_target"]
    },
    {
      "scene_number": 11,
      "caption": "The magic helper breaks the target's chains.",
      "visual_description": "Magic helper kneels, one hand on the rusty manacles, a soft blue glow spreading from her palm as the chains crack and fall away.",
      "characters": ["magic_helper", "rescue_target", "map_reader"]
    },
    {
      "scene_number": 12,
      "caption": "Patrols converge on the plaza.",
      "visual_description": "Helmets and spear tips appear at three archways leading into the plaza, guards shouting as they form a tightening ring.",
      "characters": ["patrol_guard_leader", "patrol_guard_follower", "map_reader", "scout", "magic_helper", "rescue_target"]
    },
    {
      "scene_number": 13,
      "caption": "The map reader leads a dash through a gatehouse.",
      "visual_description": "Party runs through a low stone gatehouse, map reader pointing toward a distant arch, a guard's crossbow bolt chipping the wall behind them.",
      "characters": ["map_reader", "scout", "magic_helper", "rescue_target", "patrol_guard_follower"]
    },
    {
      "scene_number": 14,
      "caption": "The bridge controls are guarded by a sleepy official.",
      "visual_description": "Small stone room with a heavy lever, a drowsy-looking official in a creased tunic slouched on a stool, keys dangling from his belt.",
      "characters": ["bridge_official", "scout", "magic_helper", "map_reader", "rescue_target"]
    },
    {
      "scene_number": 15,
      "caption": "The scout distracts the official with a shiny coin.",
      "visual_description": "Scout flips a brass coin that catches the lamplight; the official's eyes track it, allowing the magic helper to slip the keys from his belt.",
      "characters": ["scout", "bridge_official", "magic_helper", "map_reader", "rescue_target"]
    },
    {
      "scene_number": 16,
      "caption": "The lever lowers the escape bridge.",
      "visual_description": "Magic helper and map reader together pull the heavy iron lever, the rumble of chains audible as a drawbridge outside descends with a groan.",
      "characters": ["magic_helper", "map_reader", "scout", "rescue_target", "bridge_official"]
    },
    {
      "scene_number": 17,
      "caption": "They flee across the stone bridge.",
      "visual_description": "Narrow stone bridge spanning a dry ravine, party running single file under a moonlit sky, old banners tied to the bridge posts flapping behind them.",
      "characters": ["map_reader", "scout", "magic_helper", "rescue_target"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes into the open plain.",
      "visual_description": "Last view of the ruined city behind them as they crest a hill, the bridge still raised, the towers and banners growing small in the twilight.",
      "characters": ["map_reader", "scout", "magic_helper", "rescue_target"]
    }
  ]
}

